(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.15)*8+Math.cos(sy*0.02-t*0.1)*6;
  const w2y = Math.cos(sy*0.022-t*0.12)*8+Math.sin(sx*0.019+t*0.18)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+1)*70,0.05,1.8],
    [200+Math.sin(t*0.7+1)*90,220+Math.cos(t*0.3+4)*60,0.13,2.4],
    [300+Math.cos(t*0.4+3)*80,30+Math.sin(t*0.5+2)*40,0.075,2.2]
  ];
  let aS=0,iS=0,fd=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    fd+=Math.cos(d*f*0.5-t*sp*0.4+0.8);
  }
  const act=aS/10,inh=iS/10,fdd=fd/10;
  const bg1=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2;
  const bg2=Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2;
  const bg3=Math.sin(fx*0.035+fy*0.025-t*0.6)*Math.cos(fx*0.03-fy*0.06+t*0.9);
  const bg=bg1+bg2+bg3*0.3;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2);
  const ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const ring=Math.sin(dist*0.08-t*1.8)*0.3;
  const cX=Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5;
  const cY=Math.cos(fx*0.12-t*0.3)*Math.sin(fy*0.13+t*0.2);
  const cell=(Math.sin(cX*1.5)*Math.sin(cY*1.5))*0.3;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((fdd*0.5+act*0.3-inh*0.5+ring)*1.8);
  const diff=r1*0.6+r2*0.25+cell*0.15;
  const glow=Math.exp(-dist*0.008)*0.2;
  const v=Math.max(0,Math.min(1,diff*0.5+0.5+glow));
  const pal=[[6,12,52],[10,45,85],[12,78,108],[18,120,125],[30,155,130],[120,185,120],[210,195,85],[225,155,75],[210,110,80],[175,65,75],[120,35,65],[65,18,55],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(r1*Math.PI)*0.15;
  const edge=Math.abs(r1)>0.65?1.2:Math.abs(r2)>0.6?1.1:1.0;
  const hl=Math.max(0,Math.sin(r1*r2*Math.PI*2))*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+hl*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+hl*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+hl*40)|0)
  ];
}
